entities.syntax:
DWORD AddVirtualDiskParent(
[in] HANDLE VirtualDiskHandle,
[in] PCWSTR ParentPath);

DWORD DetachVirtualDisk(
  [in] HANDLE VirtualDiskHandle,
  [in] DETACH_VIRTUAL_DISK_FLAG Flags,
  [in] ULONG ProviderSpecificFlags
);

DWORD GetVirtualDiskInformation(
[in]                HANDLE                 VirtualDiskHandle,   [in, out]           PULONG                 VirtualDiskInfoSize,   [in, out]           PGET_VIRTUAL_DISK_INFO VirtualDiskInfo,
[in, out, optional] PULONG                 SizeUsed);

typedef struct _EXPAND_VIRTUAL_DISK_PARAMETERS {
  EXPAND_VIRTUAL_DISK_VERSION Version;
  union {
    struct {
      ULONGLONG NewSize;
    } Version1;
  };
} EXPAND_VIRTUAL_DISK_PARAMETERS;

typedef struct _GET_VIRTUAL_DISK_INFO {
  GET_VIRTUAL_DISK_INFO_VERSION Version;
  union {
    struct {
      ULONGLONG VirtualSize;
      ULONGLONG PhysicalSize;
      ULONG     BlockSize;
      ULONG     SectorSize;
    } Size;
    GUID        Identifier;
    struct {
      BOOL      ParentResolved;
      WCHAR     ParentLocationBuffer[1];
    } ParentLocation;
    GUID        ParentIdentifier;
    ULONG       ParentTimestamp;
  };
} GET_VIRTUAL_DISK_INFO;

typedef struct _QUERY_CHANGES_VIRTUAL_DISK_RANGE {
ULONG64 ByteOffset;   ULONG64 ByteLength;   ULONG64 Reserved;
} QUERY_CHANGES_VIRTUAL_DISK_RANGE, *PQUERY_CHANGES_VIRTUAL_DISK_RANGE;

typedef struct _STORAGE_DEPENDENCY_INFO {
  STORAGE_DEPENDENCY_INFO_VERSION Version;
  ULONG NumberEntries;
  union {
    STORAGE_DEPENDENCY_INFO_TYPE_1 Type1;
    STORAGE_DEPENDENCY_INFO_TYPE_2 Type2;
  };
} STORAGE_DEPENDENCY_INFO;

typedef enum _ATTACH_VIRTUAL_DISK_FLAG {
  VIRTUAL_DISK_FLAG_NONE = 0x0,
  VIRTUAL_DISK_FLAG_READ_ONLY = 0x1,
  VIRTUAL_DISK_FLAG_BOOT = 0x2,
  VIRTUAL_DISK_FLAG_NO_BROADCAST = 0x4,
  VIRTUAL_DISK_FLAG_PROVIDER_SPECIFIC = 0x80000000
} ATTACH_VIRTUAL_DISK_FLAG;

typedef enum _COMPACT_VIRTUAL_DISK_FLAG {
  COMPACT_VIRTUAL_DISK_FLAG_NONE = 0x0,
  COMPACT_VIRTUAL_DISK_FLAG_NO_ZERO_SCAN = 0x1,
  COMPACT_VIRTUAL_DISK_FLAG_NO_BLOCK_MOVES = 0x2
} COMPACT_VIRTUAL_DISK_FLAG;

DWORD ApplySnapshotVhdSet(
[in] HANDLE                                  VirtualDiskHandle,   [in] const PAPPLY_SNAPSHOT_VHDSET_PARAMETERS Parameters,
[in] APPLY_SNAPSHOT_VHDSET_FLAG              Flags);

DWORD CompactVirtualDisk(
[in]           HANDLE                           VirtualDiskHandle,   [in]           COMPACT_VIRTUAL_DISK_FLAG        Flags,
[in, optional] PCOMPACT_VIRTUAL_DISK_PARAMETERS Parameters,   [in, optional] LPOVERLAPPED                     Overlapped);

DWORD DeleteSnapshotVhdSet(
[in] HANDLE                                   VirtualDiskHandle,   [in] const PDELETE_SNAPSHOT_VHDSET_PARAMETERS Parameters,
[in] DELETE_SNAPSHOT_VHDSET_FLAG              Flags);

DWORD DeleteVirtualDiskMetadata(
[in] HANDLE     VirtualDiskHandle,
[in] const GUID *Item);

DWORD ExpandVirtualDisk(
[in]           HANDLE                          VirtualDiskHandle,   [in]           EXPAND_VIRTUAL_DISK_FLAG        Flags,
[in]           PEXPAND_VIRTUAL_DISK_PARAMETERS Parameters,   [in, optional] LPOVERLAPPED                    Overlapped);

DWORD GetVirtualDiskPhysicalPath(
[in]            HANDLE VirtualDiskHandle,   [in, out]       PULONG DiskPathSizeInBytes,
[out, optional] PWSTR  DiskPath);

DWORD MergeVirtualDisk(
[in]           HANDLE                         VirtualDiskHandle,   [in]           MERGE_VIRTUAL_DISK_FLAG        Flags,
[in]           PMERGE_VIRTUAL_DISK_PARAMETERS Parameters,   [in, optional] LPOVERLAPPED                   Overlapped);

typedef struct _MIRROR_VIRTUAL_DISK_PARAMETERS {
    MIRROR_VIRTUAL_DISK_VERSION Version;
    union {
        struct {
            PCWSTR MirrorVirtualDiskPath;
        } Version1;
    };
} MIRROR_VIRTUAL_DISK_PARAMETERS, *PMIRROR_VIRTUAL_DISK_PARAMETERS;

DWORD MirrorVirtualDisk(
[in] HANDLE                          VirtualDiskHandle,   [in] MIRROR_VIRTUAL_DISK_FLAG        Flags,
[in] PMIRROR_VIRTUAL_DISK_PARAMETERS Parameters,   [in] LPOVERLAPPED                    Overlapped);

typedef enum _MODIFY_VHDSET_VERSION {
  MODIFY_VHDSET_VERSION_1 = 1,
  MODIFY_VHDSET_VERSION_2 = 2,
  MODIFY_VHDSET_VERSION_3 = 3
} MODIFY_VHDSET_VERSION, *PMODIFY_VHDSET_VERSION;

DWORD RawSCSIVirtualDisk(
[in]  HANDLE                                  VirtualDiskHandle,   [in]  const PRAW_SCSI_VIRTUAL_DISK_PARAMETERS Parameters,
[in]  RAW_SCSI_VIRTUAL_DISK_FLAG              Flags,   [out] PRAW_SCSI_VIRTUAL_DISK_RESPONSE         Response);

typedef struct _RESIZE_VIRTUAL_DISK_PARAMETERS {
    RESIZE_VIRTUAL_DISK_VERSION Version;
    union {
        struct {
            ULONGLONG NewSize;
        } Version1;
    };
} RESIZE_VIRTUAL_DISK_PARAMETERS, *PRESIZE_VIRTUAL_DISK_PARAMETERS;

DWORD ResizeVirtualDisk(
[in]           HANDLE                          VirtualDiskHandle,   [in]           RESIZE_VIRTUAL_DISK_FLAG        Flags,
[in]           PRESIZE_VIRTUAL_DISK_PARAMETERS Parameters,   [in, optional] LPOVERLAPPED                    Overlapped);

typedef struct _SET_VIRTUAL_DISK_INFO {   SET_VIRTUAL_DISK_INFO_VERSION Version;   union {
PCWSTR ParentFilePath;     GUID   UniqueIdentifier;     struct {
ULONG  ChildDepth;
PCWSTR ParentFilePath;     } ParentPathWithDepthInfo;
ULONG  VhdPhysicalSectorSize;     GUID   VirtualDiskId;
BOOL   ChangeTrackingEnabled;     struct {
GUID   LinkageId;
PCWSTR ParentFilePath;
} ParentLocator;   };
} SET_VIRTUAL_DISK_INFO, *PSET_VIRTUAL_DISK_INFO;

DWORD SetVirtualDiskInformation(
[in] HANDLE                 VirtualDiskHandle,
[in] PSET_VIRTUAL_DISK_INFO VirtualDiskInfo);

DWORD TakeSnapshotVhdSet(
[in] HANDLE                                 VirtualDiskHandle,   [in] const PTAKE_SNAPSHOT_VHDSET_PARAMETERS Parameters,
[in] TAKE_SNAPSHOT_VHDSET_FLAG              Flags);
